mapper.select:
SELECT pp.CREATED_BY,afe.FC_ESTIMATE_ID, afe.PROJECT_ID, afe.ESTIMATE_NUM, afe.ESTIMATE_DATE, afe.EMPLOYEE_ID , ( SELECT em.name FROM fnd_employee em WHERE em.employee_id = afe.EMPLOYEE_ID ) AS EMPLOYEE_ID_N, afe.UNIT_ID , ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = afe.unit_id ) AS unit_id_n, afe.FIVE_CLASS_PLAN , ( SELECT afcp.description FROM ast_five_class_plan afcp WHERE afcp.FIVE_CLASS_PLAN = afe.FIVE_CLASS_PLAN AND afcp.ENABLED_FLAG = 'Y' ) AS FIVE_CLASS_PLAN_N, pp.DATA_CLASS, pp.CONTRACT_NAME, afe.CONTRACT_NUMBER, pp.TENANT_ID , ( SELECT b.bp_name FROM hls_bp_master b WHERE b.bp_id = pp.tenant_id ) AS tenant_id_n,
-- CASE -- -- WHEN pp.BUSINESS_TYPE in('T+N_LEASE_FACTORING','T+0_LEASE_FACTORING') THEN -- ( SELECT wm_concat(b.bp_name separator ',') -- FROM hls_bp_master b ,prj_project_bp hclcb -- WHERE pp.PROJECT_ID = hclcb.PROJECT_ID -- and b.bp_id = hclcb.bp_id -- and hclcb.bp_type = 'RECEIVABLE_DEBTOR' -- ) -- WHEN pp.BUSINESS_TYPE in('LEASE_WITHOUT_RECOURSE_IN','OPERATING_LEASE_WITHOUT_RECOURSE_IN') THEN -- ( SELECT wm_concat(b.bp_name separator ',') -- FROM hls_bp_master b ,prj_project_bp hclcb -- WHERE pp.PROJECT_ID = hclcb.PROJECT_ID -- and b.bp_id = hclcb.bp_id -- and hclcb.bp_type = 'ASSET_TRANSFEROR' -- ) -- ELSE -- ( SELECT wm_concat(b.bp_name separator ',') -- FROM hls_bp_master b ,prj_project_bp hclcb -- WHERE pp.PROJECT_ID = hclcb.PROJECT_ID -- and b.bp_id = hclcb.bp_id -- and hclcb.bp_type = 'TENANT' -- ) -- END AS tenant_id_n,
pp.BUSINESS_TYPE , ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'HLS200.LEASING_PRODUCT_DETAIL' AND pp.BUSINESS_TYPE = v.CODE_VALUE ) AS BUSINESS_TYPE_N, afe.SYS_TEN_CLASS_RESULT , CASE WHEN afe.SYS_TEN_CLASS_RESULT != '' THEN ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'ASSET_CLASSIFICATION_RESULTS' AND afe.SYS_TEN_CLASS_RESULT = v.CODE_VALUE ) ELSE ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'ASSET_CLASSIFICATION_RESULTS' AND ( SELECT afer.FIVE_CLASS_CODE_BY_SYSTEM
FROM ast_fc_estimate_result afer WHERE afer.FC_ESTIMATE_ID = afe.FC_ESTIMATE_ID ) = v.CODE_VALUE ) END AS SYS_TEN_CLASS_RESULT_N,
afe.START_SCORE_DESC, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'QUALITATIVE_ANALYSIS' AND afe.START_SCORE_DESC = v.CODE_VALUE ) START_SCORE_DESC_N,
afe.START_TEN_CLASS_RESULT , CASE WHEN afe.START_TEN_CLASS_RESULT !='' THEN ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'QUANTITATIVE_INDICATORS' AND afe.START_TEN_CLASS_RESULT = v.CODE_VALUE )ELSE ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'QUANTITATIVE_INDICATORS' AND afe.START_SCORE_DESC = v.CODE_VALUE ) END AS START_TEN_CLASS_RESULT_N,
afe.FINAL_ASSETS_CLASS_RESULT , CASE WHEN afe.FINAL_ASSETS_CLASS_RESULT != '' THEN ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'ASSET_CLASSIFICATION_RESULTS' AND afe.FINAL_ASSETS_CLASS_RESULT = v.CODE_VALUE ) ELSE ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'QUANTITATIVE_INDICATORS' AND afe.START_SCORE_DESC = v.CODE_VALUE ) END AS FINAL_ASSETS_CLASS_RESULT_N, afe.RAISE_STATUS , ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'LON.CONTRACT_WITHDRAW_STATUS' AND afe.RAISE_STATUS = v.CODE_VALUE ) AS RAISE_STATUS_N, afe.BREAK_RATE, afe.NOW_COUNT_STATUS , ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'LON.CONTRACT_WITHDRAW_STATUS' AND afe.NOW_COUNT_STATUS = v.CODE_VALUE ) AS NOW_COUNT_STATUS_N, afe.NOW_COUNT, afe.STATUS, afe.PLAN_ID , ( SELECT pp.plan_number FROM prj_check_plan pp WHERE pp.plan_id = afe.PLAN_ID ) AS PLAN_ID_N, afe.NOW_COUNT, afe.BREAK_RATE , ( SELECT meaning FROM sys_code_value_b_v v WHERE v.CODE = 'CREDIT.APPROVE_STATUS' AND v.code_value = afe.STATUS ) AS STATUS_N FROM ast_fc_estimate afe, prj_project pp
pp.PROJECT_ID = afe.PROJECT_ID and pp.DATA_CLASS = 'VIRTUAL_CON'
and (pp.created_by = #{request.userId} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{createdBy}))
and afe.ESTIMATE_NUM = #{estimateNum}
and afe.FC_ESTIMATE_ID = #{fcEstimateId}
and afe.CONTRACT_NUMBER = #{contractNumber}
and afe.CONTRACT_NUMBER = #{projectNumber}
and afe.FIVE_CLASS_PLAN = #{fiveClassPlan}
and afe.EMPLOYEE_ID = #{employeeId}
and afe.UNIT_ID = #{unitId}
and afe.RAISE_STATUS = #{raiseStatus}
and afe.NOW_COUNT_STATUS = #{nowCountStatus}
and afe.ESTIMATE_DATE between #{estimateDateFrom} and #{estimateDateTo}
ORDER BY afe.FC_ESTIMATE_ID desc

select ( select afcrd.FIVE_CLASS_TARGET from ast_five_class_rule afcr,ast_five_class_rule_detail afcrd,ast_five_class_plan afcp,ast_five_class_code afcc where afcr.FIVE_CLASS_RULE_ID = afcrd.FIVE_CLASS_RULE_ID and afcp.FIVE_CLASS_PLAN = afcc.FIVE_CLASS_PLAN and afcr.FIVE_CLASS_RULE_ID = afcc.FIVE_CLASS_RULE_ID and afcp.FIVE_CLASS_PLAN = afe.FIVE_CLASS_PLAN and rownum=1 ) FIVE_CLASS_TARGET,
( select afcc.FIVE_CLASS_RULE_ID from ast_five_class_rule afcr,ast_five_class_rule_detail afcrd,ast_five_class_plan afcp,ast_five_class_code afcc where afcr.FIVE_CLASS_RULE_ID = afcrd.FIVE_CLASS_RULE_ID and afcp.FIVE_CLASS_PLAN = afcc.FIVE_CLASS_PLAN and afcr.FIVE_CLASS_RULE_ID = afcc.FIVE_CLASS_RULE_ID and afcp.FIVE_CLASS_PLAN = afe.FIVE_CLASS_PLAN and rownum=1 ) FIVE_CLASS_RULE_ID from ast_fc_estimate afe
afe.FC_ESTIMATE_ID = #{fcEstimateId}
